def b\(col, row, tmpl, powerup=None, mv=None\):
    d = {"col": col, "row": row, "templateId": tmpl}
    if powerup:
        d["powerupId"] = powerup
    if mv:
        d["movement"] = mv
    return d

def mv\(type, amp, period, phase=0.0\):
    return {"type": type, "amplitude": amp, "period": period, "phaseOffset": phase}

def save\(idx, name, bricks\):
    lvl_id = f"level_{idx:02d}"
    data = {"id": lvl_id, "displayName": name, "grid": GRID, "bricks": bricks}
    path = os.path.join\(OUT_DIR, lvl_id + ".json"\)
    with open\(path, "w"\) as f:
        json.dump\(data, f, indent=2\)
    print\(f"Wrote {path} \({len\(bricks\)} bricks\)"\)

